using System.Globalization;using Microsoft.Data.Sqlite;using StockSyncAI.Api.Models;namespace StockSyncAI.Api.Database;
public sealed class InvoicePostingRepository(SqliteConnectionFactory factory):IInvoicePostingRepository
{
 private const string Columns="id,invoice_id,review_fingerprint,snapshot_json,state,attempt_count,safe_error,result_json,confirmed_utc,created_utc,updated_utc";
 public async Task<InvoicePostingRecord?> GetAsync(Guid invoiceId,string fingerprint,CancellationToken token=default){await using var c=await factory.OpenAsync(token);await using var q=c.CreateCommand();q.CommandText=$"SELECT {Columns} FROM invoice_postings WHERE invoice_id=$invoice AND review_fingerprint=$fingerprint";q.Parameters.AddWithValue("$invoice",invoiceId.ToString("D"));q.Parameters.AddWithValue("$fingerprint",fingerprint);await using var r=await q.ExecuteReaderAsync(token);return await r.ReadAsync(token)?Read(r):null;}
 public async Task<IReadOnlyList<InvoicePostingRecord>> ListAsync(Guid invoiceId,CancellationToken token=default){await using var c=await factory.OpenAsync(token);await using var q=c.CreateCommand();q.CommandText=$"SELECT {Columns} FROM invoice_postings WHERE invoice_id=$invoice ORDER BY updated_utc DESC";q.Parameters.AddWithValue("$invoice",invoiceId.ToString("D"));await using var r=await q.ExecuteReaderAsync(token);var list=new List<InvoicePostingRecord>();while(await r.ReadAsync(token))list.Add(Read(r));return list;}
 public async Task<InvoicePostingRecord> PrepareAsync(Guid invoiceId,string fingerprint,string snapshot,DateTimeOffset now,CancellationToken token=default){var e=await GetAsync(invoiceId,fingerprint,token);if(e?.State is PostingStates.Posted or PostingStates.Posting or PostingStates.OutcomeUnknown)return e;var id=e?.Id??Guid.NewGuid();await using var c=await factory.OpenAsync(token);await using var q=c.CreateCommand();q.CommandText="""INSERT INTO invoice_postings(id,invoice_id,review_fingerprint,snapshot_json,state,attempt_count,safe_error,result_json,confirmed_utc,created_utc,updated_utc) VALUES($id,$invoice,$fingerprint,$snapshot,'Prepared',0,NULL,NULL,NULL,$now,$now) ON CONFLICT(invoice_id,review_fingerprint) DO UPDATE SET snapshot_json=$snapshot,state='Prepared',safe_error=NULL,result_json=NULL,confirmed_utc=NULL,updated_utc=$now WHERE invoice_postings.state IN ('Prepared','FailedSafeToRetry','Blocked');""";Add(q,"$id",id.ToString("D"));Add(q,"$invoice",invoiceId.ToString("D"));Add(q,"$fingerprint",fingerprint);Add(q,"$snapshot",snapshot);Add(q,"$now",now.ToString("O"));await q.ExecuteNonQueryAsync(token);return(await GetAsync(invoiceId,fingerprint,token))!;}
 public async Task<bool> TryStartAsync(Guid id,DateTimeOffset now,CancellationToken token=default){await using var c=await factory.OpenAsync(token);await using var q=c.CreateCommand();q.CommandText="UPDATE invoice_postings SET state='Posting',attempt_count=attempt_count+1,safe_error=NULL,updated_utc=$now WHERE id=$id AND state IN ('Prepared','FailedSafeToRetry')";Add(q,"$id",id.ToString("D"));Add(q,"$now",now.ToString("O"));return await q.ExecuteNonQueryAsync(token)==1;}
 public async Task SetOutcomeAsync(Guid id,string state,string? error,string? result,DateTimeOffset? confirmed,DateTimeOffset now,CancellationToken token=default){if(state is not(PostingStates.Posted or PostingStates.FailedSafeToRetry or PostingStates.OutcomeUnknown or PostingStates.Blocked))throw new ArgumentOutOfRangeException(nameof(state));await using var c=await factory.OpenAsync(token);await using var q=c.CreateCommand();q.CommandText="UPDATE invoice_postings SET state=$state,safe_error=$error,result_json=$result,confirmed_utc=$confirmed,updated_utc=$now WHERE id=$id AND state='Posting'";Add(q,"$id",id.ToString("D"));Add(q,"$state",state);Add(q,"$error",error);Add(q,"$result",result);Add(q,"$confirmed",confirmed?.ToString("O"));Add(q,"$now",now.ToString("O"));if(await q.ExecuteNonQueryAsync(token)!=1)throw new InvalidOperationException("Posting state changed unexpectedly.");}
 public async Task<int> RecoverInterruptedAsync(DateTimeOffset now,CancellationToken token=default){await using var c=await factory.OpenAsync(token);await using var q=c.CreateCommand();q.CommandText="UPDATE invoice_postings SET state='OutcomeUnknown',safe_error='The application stopped while POS posting was in progress. Reconcile this invoice before any retry.',updated_utc=$now WHERE state='Posting'";Add(q,"$now",now.ToString("O"));return await q.ExecuteNonQueryAsync(token);}
 private static InvoicePostingRecord Read(SqliteDataReader r)=>new(Guid.Parse(r.GetString(0)),Guid.Parse(r.GetString(1)),r.GetString(2),r.GetString(3),r.GetString(4),r.GetInt32(5),Text(r,6),Text(r,7),Date(r,8),Date(r.GetString(9))!.Value,Date(r.GetString(10))!.Value);private static string? Text(SqliteDataReader r,int i)=>r.IsDBNull(i)?null:r.GetString(i);private static DateTimeOffset? Date(SqliteDataReader r,int i)=>r.IsDBNull(i)?null:Date(r.GetString(i));private static DateTimeOffset? Date(string v)=>DateTimeOffset.Parse(v,CultureInfo.InvariantCulture);private static void Add(SqliteCommand q,string n,object? v)=>q.Parameters.AddWithValue(n,v??DBNull.Value);
}
